var n = (flow.get('candump_restarts') || 0) + 1;
flow.set('candump_restarts', n);

var rc = (typeof msg.payload === 'object') ? JSON.stringify(msg.payload) : msg.payload;
node.warn('czone candump exited (rc ' + rc + ') — restart #' + n + ' in 5s');
node.status({ fill: 'red', shape: 'ring', text: 'candump exited — restart #' + n });
return msg;

// exec stdout arrives in chunks, not lines: reassemble and decode every line
var chunk = msg.payload;
if (Buffer.isBuffer(chunk)) chunk = chunk.toString('utf8');
if (typeof chunk !== 'string') return null;

chunk = (context.get('partial') || '') + chunk;
var lines = chunk.split('\n');
context.set('partial', lines.pop());

var msgs = [];
for (var n = 0; n < lines.length; n++) {
    var match = lines[n].match(/\scan\d+\s+([0-9A-Fa-f]+)\s+\[(\d+)\]\s+([0-9A-Fa-f\s]+)/);
    if (!match) continue;

    var canid = parseInt(match[1], 16); // full 29-bit ID
    var hexBytes = match[3].trim().split(/\s+/);
    msgs.push({
        payload: {
            canid: canid,
            src: canid & 0xFF,
            dlc: parseInt(match[2], 10),
            data: Buffer.from(hexBytes.map(function (h) { return parseInt(h, 16); }))
        }
    });
}

return [msgs];

// PGN 127501 (Binary Switch Bank Status) decoder.
// Trust ONLY bank instance 1 (the CZone Output Interface): another device on the
// bus (src 0x0C) spams 127501 instance 0 "all OFF" at 5Hz — ingesting those flips
// the tracked state several times a second and strobes the lights (the v6.0 bug).
var f = msg.payload;
if (!f || !f.data || f.data.length < 4) return null;
if (((f.canid >> 8) & 0x3FFFF) !== 0x1F20D) return null; // 127501 only
var d = f.data;
if (d[0] !== 0x01) return null; // bank instance 1 only

var now = Date.now();
var states = flow.get('czState') || {};
var names = {1:'Bilge1',2:'Bilge2',3:'Horn',4:'Helm',5:'Nav',6:'Anchor',7:'Red',8:'Fly',9:'Underwater',10:'Bow1',11:'Bow2'};
var outputs = [null,null,null,null,null,null,null,null,null,null,null];
var changed = [];

for (var sw = 1; sw <= 11; sw++) {
    var v = (d[Math.floor((sw-1)/4)+1] >> (((sw-1)%4)*2)) & 0x03;
    if (v > 1) continue; // 2/3 = error/unavailable
    var prev = states[sw];
    states[sw] = {state: v, ts: now};
    if (prev && prev.state === v) continue;
    // Push to virtual switch only on change: idempotent D-Bus writes saturate
    // the bus and starve user clicks.
    var m = {payload: {}, _czoneSync: true};
    m.payload['/SwitchableOutput/output_1/State'] = v;
    outputs[sw-1] = m;
    changed.push(names[sw] + (v ? ' ON' : ' OFF'));
}
flow.set('czState', states);

if (!changed.length) return null;
node.status({fill: 'green', shape: 'dot',
    text: changed.join(', ') + ' @' + new Date().toLocaleTimeString()});
return outputs;

var states = flow.get('czState') || {};
var pending = flow.get('czPending') || {};
var holds = flow.get('czHolds') || {};
var names = {1:'Bilge Pump 1',2:'Bilge Pump 2',3:'Horn',4:'Illumination Helm',5:'Navigation Lights',6:'Anchor Light',7:'Red Light',8:'Illumination Fly',9:'Underwater Light',10:'Bow light 1',11:'Bow light 2'};
var now = Date.now();
var lines = [];
for (var i = 1; i <= 11; i++) {
    var s = states[i];
    var st = s ? ((s.state === 1 ? 'ON ' : 'OFF') + ' ' + Math.round((now - s.ts)/1000) + 's ago') : '???';
    var flags = (pending[i] ? ' [pending ' + (pending[i].target ? 'ON' : 'OFF') + ']' : '') + (holds[i] ? ' [held]' : '');
    lines.push('Sw' + (i<10?' ':'') + i + ' ' + st + '  ' + names[i] + flags);
}
msg.payload = lines.join('\n');
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:1, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:2, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:3, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:4, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:5, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:6, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:7, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:8, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:9, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:10, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:11, action: msg.payload ? 'on' : 'off'};
return msg;

// CZone Control Engine v6.1
// Input: { switch: 1-11, action: 'on'|'off'|'toggle' }
// Sends PGN 127502 instance 10 — direct set-state (confirmed by bus capture
// 2026-07-06: CZone applies bank-10 commands in <10ms, accepts source 0xFE).
// Confirmation, retry and keep-alive run in the Confirm & Keep-alive engine.

var now = Date.now();

// Deploy-echo guard: on (re)deploy every virtual switch emits its initial OFF
// out the command side before any 127501 has been decoded. Drop everything for
// 12s — by then candump is running and real state is synced into the switches.
var deployTs = flow.get('deployTs') || 0;
if (now - deployTs < 12000) {
    node.status({fill:'grey', shape:'ring', text:'deploy guard (' + Math.ceil((12000 - (now - deployTs))/1000) + 's left)'});
    return null;
}

var cmd = msg.payload;
if (!cmd || !cmd.switch || !cmd.action) {
    node.warn('Need {switch: 1-11, action: on|off|toggle}');
    return null;
}

var sw = parseInt(cmd.switch);
var action = String(cmd.action).toLowerCase();
if (!(sw >= 1 && sw <= 11)) { node.warn('Switch must be 1-11'); return null; }

var names = {1:'Bilge Pump 1',2:'Bilge Pump 2',3:'Horn',4:'Helm Lights',5:'Nav Lights',6:'Anchor Light',7:'Red Light',8:'Flybridge Lights',9:'Underwater Light',10:'Bow Light 1',11:'Bow Light 2'};

var states = flow.get('czState') || {};
var st = states[sw];
var fresh = st && (now - st.ts < 10000); // stale state never blocks a command

var target;
if (action === 'on') target = 1;
else if (action === 'off') target = 0;
else if (action === 'toggle') target = (st && st.state === 1) ? 0 : 1;
else return null;

// Revert-echo guard: the virtual-switch node strips _czoneSync, so a revert
// write echoes back out the command side. Drop commands mirroring a recent revert.
var rr = (flow.get('czRecentRevert') || {})[sw];
if (rr && rr.value === target && now - rr.ts < 3000) {
    node.status({fill:'grey', shape:'ring', text:names[sw] + ' revert echo dropped'});
    return null;
}

// Fresh-state dedupe: stops sync echoes from becoming commands. Also correct for
// keypad-lit circuits: CZone latches those natively, no hold needed.
if (fresh && st.state === target) {
    node.status({fill:'yellow', shape:'ring', text:names[sw] + ' already ' + (target ? 'ON' : 'OFF')});
    return null;
}

var pending = flow.get('czPending') || {};
var p = pending[sw];
if (p && p.target === target) {
    node.status({fill:'yellow', shape:'ring', text:names[sw] + ' already pending'});
    return null;
}
pending[sw] = {target: target, cmdTs: now, lastSend: now, sends: 1};
flow.set('czPending', pending);

// An OFF releases the keep-alive hold immediately so it can't fight the command
if (target === 0) {
    var holds = flow.get('czHolds') || {};
    if (holds[sw]) { delete holds[sw]; flow.set('czHolds', holds); }
}

// Build PGN 127502 instance 10: 2 bits per switch, 00=Off 01=On 11=NoChange
var data = [0x0A, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF];
var byteIdx = Math.floor((sw - 1) / 4) + 1;
var bitPos = ((sw - 1) % 4) * 2;
data[byteIdx] = (data[byteIdx] & (~(0x03 << bitPos) & 0xFF)) | (target << bitPos);
var hex = data.map(function(b) { return ('0' + b.toString(16).toUpperCase()).slice(-2); }).join('');

msg.payload = 'cansend can0 09F20EFE#' + hex;
msg.switchNum = sw;
msg.switchName = names[sw];
msg.reason = target ? 'ON' : 'OFF';

node.status({fill:'blue', shape:'dot', text:names[sw] + ' ' + msg.reason + ' @' + new Date().toLocaleTimeString()});
return msg;

// Runs every 250ms.
// 1) Confirm pending commands against 127501 state newer than the command;
//    resend after 500ms (max 3 transmissions); give up and revert after 5s.
// 2) Keep-alive: CZone reverts a bank-10 commanded output ~10s after the last
//    command frame (measured 2026-07-02), so confirmed VRM-commanded ONs are
//    re-asserted every 1s. A hold is released when an OFF is commanded or the
//    output is observed OFF with no command in flight (keypad/CZone turned it
//    off). Keypad-lit circuits are never held: CZone latches those natively.

var now = Date.now();
var states = flow.get('czState') || {};
var pending = flow.get('czPending') || {};
var holds = flow.get('czHolds') || {};
var names = {1:'Bilge Pump 1',2:'Bilge Pump 2',3:'Horn',4:'Helm Lights',5:'Nav Lights',6:'Anchor Light',7:'Red Light',8:'Flybridge Lights',9:'Underwater Light',10:'Bow Light 1',11:'Bow Light 2'};

function frame(sw, val) {
    var data = [0x0A, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF];
    var byteIdx = Math.floor((sw - 1) / 4) + 1;
    var bitPos = ((sw - 1) % 4) * 2;
    data[byteIdx] = (data[byteIdx] & (~(0x03 << bitPos) & 0xFF)) | (val << bitPos);
    return 'cansend can0 09F20EFE#' + data.map(function(b) { return ('0' + b.toString(16).toUpperCase()).slice(-2); }).join('');
}

var sends = [];
var reverts = [];

Object.keys(pending).forEach(function(k) {
    var sw = parseInt(k), p = pending[k];
    var st = states[sw];
    if (st && st.ts >= p.cmdTs && st.state === p.target) {
        // Confirmed. VRM-commanded ONs get a keep-alive hold.
        delete pending[k];
        if (p.target === 1) holds[sw] = {lastAssert: now};
        return;
    }
    if (now - p.cmdTs > 5000) {
        // Give up: revert the virtual switch to the last real CZone state.
        delete pending[k];
        var rv = st ? st.state : 0;
        var rr = flow.get('czRecentRevert') || {};
        rr[sw] = {value: rv, ts: now};
        flow.set('czRecentRevert', rr);
        reverts.push({sw: sw, state: rv});
        node.warn('CZone: ' + names[sw] + ' ' + (p.target ? 'ON' : 'OFF') + ' unconfirmed after 5s (' + p.sends + ' tx) — reverting virtual switch');
        return;
    }
    if (now - p.lastSend >= 500 && p.sends < 3) {
        sends.push({payload: frame(sw, p.target)});
        p.lastSend = now;
        p.sends++;
    }
});

Object.keys(holds).forEach(function(k) {
    var sw = parseInt(k), h = holds[k];
    if (pending[sw]) return; // a command in flight owns this switch
    var st = states[sw];
    if (st && st.state === 0 && st.ts > h.lastAssert) {
        // Observed OFF newer than our last assert: keypad/CZone turned it off.
        // The decoder already synced the virtual switch; just release the hold.
        delete holds[k];
        return;
    }
    if (now - h.lastAssert >= 1000) {
        sends.push({payload: frame(sw, 1)});
        h.lastAssert = now;
    }
});

flow.set('czPending', pending);
flow.set('czHolds', holds);

var held = Object.keys(holds);
var nPend = Object.keys(pending).length;
node.status({fill: (held.length || nPend) ? 'blue' : 'grey', shape: 'dot',
    text: (nPend ? nPend + ' pending, ' : '') + (held.length ? 'holding: ' + held.map(function(k) { return names[k]; }).join(', ') : 'idle')});

return [sends, reverts];

// Route {sw, state} revert messages to the right virtual switch input
var sw = msg.sw;
if (!(sw >= 1 && sw <= 11)) return null;
var outputs = [null,null,null,null,null,null,null,null,null,null,null];
var m = {payload: {}, _czoneSync: true};
m.payload['/SwitchableOutput/output_1/State'] = msg.state;
outputs[sw - 1] = m;
return outputs;
